1	// Pure display formatting for the Status screen's health readouts (Functional Core).
2	//
3	// The relay's `GET /v1/admin/health` reports literal facts only — no ok/warn verdicts —
4	// so every presentation judgment (how an age reads, when staleness is worth a marker)
5	// lives here, where it is unit-testable, not in the API shape.
6	
7	import type { SweepRun } from '$lib/ipc';
8	
9	/**
10	 * Render a duration in seconds as a compact `uptime`-style figure: `47s` under a
11	 * minute, then the two largest units — `12m 3s`, `4h 12m`, `3d 4h`. Literal and
12	 * scannable; no rounding a day up to "1 week".
13	 */
14	export function formatDuration(seconds: number): string {
15	  const s = Math.max(0, Math.floor(seconds));
16	  if (s < 60) return `${s}s`;
17	  const units: [string, number][] = [
18	    ['d', 86_400],
19	    ['h', 3_600],
20	    ['m', 60],
21	    ['s', 1],
22	  ];
23	  const parts: string[] = [];
24	  let rest = s;
25	  for (const [name, size] of units) {
26	    const count = Math.floor(rest / size);
27	    if (count > 0 || parts.length > 0) {
28	      parts.push(`${count}${name}`);
29	      rest -= count * size;
30	    }
31	    if (parts.length === 2) break;
32	  }
33	  return parts.join(' ');
34	}
35	
36	/**
37	 * The firehose backfill window: how far back a reconnecting subscriber's cursor still
38	 * replays exactly. `null` means the event log is empty — say so literally rather than
39	 * rendering a zero that would read as "no window".
40	 */
41	export function formatBackfillWindow(seconds: number | null): string {
42	  if (seconds === null) return 'empty log';
43	  return formatDuration(seconds);
44	}
45	
46	/**
47	 * One background sweep's row on the Status screen.
48	 *
49	 * `run` is the sweep's last completed pass (`null` until its first pass after boot —
50	 * each sweep first runs one full interval after startup).
51	 *
52	 * `nowSeconds` is the current unix time, passed in so the function stays pure.
53	 *
54	 * A sweep reports two INDEPENDENT faults, and the operator's response to each differs,
55	 * so the line must let them be told apart:
56	 * - **stale** — a pass that fails outright records nothing, so a `completedAt` that
57	 *   keeps ageing means passes are not completing at all. The sweep is dead; go look at
58	 *   the server.
59	 * - **failed** — a fresh `completedAt` carrying `errors > 0` means the pass DID run and
60	 *   deliberately skipped part of its work. For blob GC that is an account whose
61	 *   reconcile failed: it is excluded from collection and leaks disk until the fault is
62	 *   fixed. One broken subject, on an otherwise living sweep; go fix that subject.
63	 *
64	 * Contract (pinned by health.test.ts):
65	 * - Returns a single monospace-friendly line; status is carried by text/glyphs,
66	 *   never color (AAA).
67	 * - Must distinguish "never ran yet" from "ran, swept nothing" — a quiet sweep is
68	 *   healthy, a missing one may not be: `null` → `not yet run`, a completed pass →
69	 *   `<age> ago · swept <n>` (`4m 0s ago · swept 7`; `swept 0` stays visible).
70	 * - Each fault appends its own NAMED segment, and a single trailing ` !` marks the line
71	 *   as wanting attention (quotaBar's glyph-not-color convention). The names are what
72	 *   make the two readable apart — an unlabelled marker could not say which fault it
73	 *   meant on a row that has both, and "swept 7 · failed 1 !" must never be mistaken for
74	 *   a louder version of "stale".
75	 * - `errors` is a count of broken subjects, not a magnitude — the relay counts failed
76	 *   operations, not the work they cost — so it is reported as a bare figure with no
77	 *   severity dressing.
78	 * - Staleness threshold is 24h. The relay doesn't report sweep intervals — prod sweeps
79	 *   run on minutes-to-hours cadences, so a full day without a completed pass is worth a
80	 *   marker on any of them, while never false-flagging a slow-but-healthy daily-ish
81	 *   sweep. `errors` needs no threshold: one skipped subject is already worth saying.
82	 */
83	export function sweepLine(run: SweepRun | null, nowSeconds: number): string {
84	  if (run === null) return 'not yet run';
85	  const age = Math.max(0, nowSeconds - run.completedAt);
86	  const parts = [`${formatDuration(age)} ago`, `swept ${run.swept}`];
87	  if (run.errors > 0) parts.push(`failed ${run.errors}`);
88	  if (age >= 86_400) parts.push('stale');
89	  const attention = run.errors > 0 || age >= 86_400 ? ' !' : '';
90	  return `${parts.join(' · ')}${attention}`;
91	}
