2	  import StatusChip, { type Status } from './StatusChip.svelte';
3	  import { shortenId } from '$lib/format';
4	  import { flagLine } from '$lib/flags';
5	  import type { AccountFlag } from '$lib/ipc';
6	
7	  // One account in the operator list — DeviceRow's dense `ls -l` register, plus the
8	  // blob-quota readout the list exists to make scannable. Handle (or an explicit
9	  // "no handle") + shortened mono DID on the left with the quota meter beneath them,
10	  // a lifecycle chip on the right. The full DID is one tap away (onclick → the
11	  // per-account screens), so the row shows a head…tail form with a VISIBLE ellipsis —
12	  // explicit truncation, never the silent kind the Literal-Truth rule forbids.
13	  // A flagged account additionally carries one ⚑ line per in-force labeler flag
14	  // (value · labeler · date — glyph + text + top-of-list position, never color alone).
15	  let {
16	    did,
17	    handle,
18	    status,
19	    quota,
20	    flags = [],
21	    onclick,
22	  }: {
23	    did: string;
24	    /** The account's handle, or null when it has none (rendered as an explicit gap). */
25	    handle: string | null;
26	    status: 'active' | 'deactivated' | 'suspended' | 'takendown';
27	    /** The monospace quota readout for this row (see format.ts `quotaBar`). */
28	    quota: string;
29	    /** In-force watched-labeler labels, newest first (empty = unflagged). */
30	    flags?: AccountFlag[];
31	    onclick?: () => void;
32	  } = $props();
33	
34	  // Lifecycle → chip tone/glyph/label. Precedence and vocabulary come from the relay;
35	  // this only picks the register: deactivated is a dormant (warning) state the user
36	  // chose, suspended and takendown are operator-imposed (critical) states.
37	  const CHIP: Record<typeof status, { chip: Status; label: string }> = {
38	    active: { chip: 'active', label: 'active' },
39	    deactivated: { chip: 'pending', label: 'deactivated' },
40	    suspended: { chip: 'error', label: 'suspended' },
41	    takendown: { chip: 'revoked', label: 'taken down' },
42	  };
43	  const chip = $derived(CHIP[status]);
44	
45	</script>
