3	/**
4	 * Render a byte count: a scannable binary-unit figure first (KiB/MiB/GiB — matching
5	 * the relay's GiB-based quota config), with the exact byte count kept alongside so
6	 * the rounding never hides the literal truth. One decimal under 10 of a unit, none
7	 * above, like `ls -lh`. Below 1 KiB the raw count IS the figure, so no parenthetical.
8	 */
9	export function formatBytes(bytes: number): string {
10	  const units = ['KiB', 'MiB', 'GiB', 'TiB'];
11	  if (bytes < 1024) return `${bytes} B`;
12	  let value = bytes;
13	  let unit = 'B';
14	  for (const next of units) {
15	    if (value < 1024) break;
16	    value /= 1024;
17	    unit = next;
18	  }
19	  const figure = value < 10 ? value.toFixed(1) : Math.round(value).toString();
20	  return `${figure} ${unit} (${bytes} B)`;
21	}
22	
23	/**
24	 * Shorten a long identifier for a single-line row with an EXPLICIT ellipsis —
25	 * `did:key:zDnae…aH2g` — keeping the method prefix and a tail so it stays
26	 * recognizable. The visible `…` is the Literal-Truth rule's alternative to
27	 * silent CSS clipping; the full value always lives one tap away in the row's
28	 * expanded panel or detail screen.
29	 */
30	export function shortenId(id: string): string {
31	  if (id.length <= 24) return id;
32	  return `${id.slice(0, 14)}…${id.slice(-4)}`;
33	}
34	
35	/** Quota-used percentage: two decimals, but never round a nonzero usage to "0.00%". */
36	export function formatPct(pct: number): string {
37	  if (pct > 0 && pct < 0.01) return '<0.01%';
38	  return `${pct.toFixed(2)}%`;
39	}
40	
41	/**
42	 * The account list's per-row blob-quota readout: a fixed-width, 5-cell text meter
43	 * followed by the literal percentage, e.g. `[▓▓░░░] 42.00%`, with a trailing ` !`
44	 * marker at ≥90% — `[▓▓▓▓▓] 95.10% !`.
45	 *
46	 * Deliberately a *text* readout, not a graphical gauge (a scrolling column of gauges
47	 * is the "chart-soup" anti-reference): the meter is monospace characters so a column
48	 * of rows aligns and scans, the exact percentage is always carried as text (status is
49	 * never signalled by shape or color alone — AAA), and the near-capacity warning is a
50	 * glyph, not a color change.
51	 *
52	 * Contract pinned by format.test.ts:
53	 * - Always `[` + exactly 5 cells (each `▓` or `░`) + `] ` + formatPct(pct).
54	 * - Fill is monotonic in pct: 0% → all `░`, 100% (and anything above) → all `▓`.
55	 * - ` !` is appended exactly when pct ≥ 90.
56	 * - Out-of-range input is clamped: pct < 0 renders as 0%, pct > 100 fills all cells
57	 *   (formatPct still reports the literal value — the meter clamps, the text doesn't).
58	 */
59	export function quotaBar(pct: number): string {
60	  // Fill rounds DOWN (terminal progress-bar convention): a cell lights only when fully
61	  // earned, so the meter never overstates how close to quota an account is — the exact
62	  // percentage alongside carries the mid-cell truth.
63	  const filled = Math.min(5, Math.max(0, Math.floor(pct / 20)));
64	  const meter = '▓'.repeat(filled) + '░'.repeat(5 - filled);
65	  const marker = pct >= 90 ? ' !' : '';
66	  return `[${meter}] ${formatPct(pct)}${marker}`;
67	}
